(function(){
'use strict';
const $=id=>document.getElementById(id),audio=window.KanjiGameAudio;
const seal=(glyph,label)=>{const n=document.createElement('div');n.className='workshop-seal';n.setAttribute('aria-hidden','true');const ring=document.createElement('i'),char=document.createElement('strong'),caption=document.createElement('span');char.textContent=glyph;caption.textContent=label;n.append(ring,char,caption);return n;};
for(const [id,char,label]of [['screen-gacha','召','文字に、命を。'],['screen-synthesis','錬','二つの力を、一つの文字へ。']]){const screen=$(id),heading=screen.querySelector('h2')?.parentElement;if(heading){heading.classList.add('workshop-heading');heading.after(seal(char,label));}screen.querySelectorAll('.glass-panel').forEach((n,i)=>{n.classList.add('workshop-panel');n.dataset.workshopPanel=String(i);});}
const workbench=$('synth-slot-1').closest('.glass-panel'),materials=$('synthesis-selectable-grid').closest('.glass-panel');
$('screen-synthesis').querySelector('.workshop-seal').after(workbench);workbench.after(materials);
const shell=$('modal-gacha').querySelector('.gacha-shell'),heading=shell.querySelector('.gacha-heading');const stage=document.createElement('div');stage.className='gacha-stage';stage.append(seal('召','墨が巡り、文字が宿る'));heading.after(stage);
const discovery=document.createElement('section');discovery.id='gacha-discovery';discovery.hidden=true;discovery.className='gacha-discovery';discovery.setAttribute('aria-live','polite');discovery.innerHTML='<p id="gacha-reveal-eyebrow" class="discovery-eyebrow">新たな文字との出会い</p><strong id="gacha-discovery-char" class="kanji-font"></strong><span id="gacha-discovery-reading"></span><span id="gacha-discovery-meta"></span><b id="gacha-reveal-stamp" class="discovery-stamp">初発見</b>';stage.append(discovery);
const content=document.createElement('div');content.className='gacha-content';for(const child of [...shell.children])if(!child.classList.contains('gacha-footer'))content.append(child);shell.prepend(content);
$('btn-gacha-skip').textContent='演出スキップ・結果をまとめて見る';$('btn-gacha-close').textContent='召喚に戻る';
const wallet=document.createElement('p');wallet.className='workshop-wallet';wallet.setAttribute('role','status');$('screen-gacha').querySelector('.workshop-seal').after(wallet);
function coins(){wallet.textContent='所持 '+Number(gameState.coins||0).toLocaleString('ja-JP')+' 文';}
const counter=$('header-coins');if(counter)new MutationObserver(coins).observe(counter,{childList:true,subtree:true,characterData:true});coins();
const dialog=document.createElement('div');dialog.id='modal-sound-settings';dialog.className='editor-overlay hidden';dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-labelledby','sound-settings-title');dialog.innerHTML='<section class="editor-panel sound-settings"><div class="editor-title"><h2 id="sound-settings-title">ゲームの音</h2><button id="sound-settings-close">閉じる</button></div><label class="sound-toggle"><input id="game-sound-enabled" type="checkbox">効果音を鳴らす</label><label class="sound-volume" for="game-sound-volume">効果音量 <output id="game-sound-level"></output></label><input id="game-sound-volume" type="range" min="0" max="100" step="1"><label class="sound-toggle"><input id="game-bgm-enabled" type="checkbox">BGMを流す</label><label class="sound-volume" for="game-bgm-volume">BGM音量 <output id="game-bgm-level"></output></label><input id="game-bgm-volume" type="range" min="0" max="100" step="1"><button id="game-audio-unlock" class="inventory-action">音を有効にする</button></section>';document.body.append(dialog);
const button=document.createElement('button');button.id='btn-game-sound-settings';button.type='button';button.textContent='音設定';button.setAttribute('aria-label','ゲームの音と音量を設定');
const battleSound=document.createElement('button');battleSound.type='button';battleSound.className='inventory-action secondary';battleSound.textContent='音設定';battleSound.onclick=()=>button.onclick();$('modal-battle-menu')?.querySelector('.editor-panel')?.append(battleSound);
const host=document.querySelector('header');if(host){host.classList.add('has-sound-settings');host.append(button);}else $('screen-gacha').querySelector('.workshop-heading').append(button);
const single=document.createElement('button');single.type='button';single.id='btn-gacha-single-repeat';single.hidden=true;single.className='inventory-action secondary';$('modal-gacha').querySelector('.gacha-footer').append(single);
function refreshSingle(){const v=gachaPresentation,eligible=v&&v.results.length===1&&['normal','rare','element'].includes(v.type)&&v.revealed.size===1&&!v.discoveryActive;single.hidden=!eligible;if(!eligible){single.disabled=true;return;}const cost=v.type==='normal'?100:300;single.disabled=gameState.coins<cost;single.textContent='もう一度召喚（'+cost+'文）';}
single.onclick=()=>{const v=gachaPresentation;if(single.disabled||!v||v.discoveryActive||Date.now()<(v.repeatAfter||0)||v.results.length!==1||v.revealed.size!==1)return;single.disabled=true;window.drawGacha(v.type);if(gachaPresentation!==v)gachaPresentation.opener=v.opener;refreshSingle();};
new MutationObserver(refreshSingle).observe($('modal-gacha'),{attributes:true,attributeFilter:['class']});refreshSingle();

let opener=null;const sync=()=>{const s=audio.settings;$('game-sound-enabled').checked=s.enabled;$('game-sound-volume').value=s.volume;$('game-sound-level').value=s.volume+'％';$('game-sound-volume').disabled=!s.enabled;const b=audio.bgmSettings;$('game-bgm-enabled').checked=b.enabled;$('game-bgm-volume').value=b.volume;$('game-bgm-level').value=b.volume+'％';$('game-bgm-volume').disabled=!b.enabled;};
button.onclick=()=>{audio.unlock();opener=document.activeElement;window.pausePlayerOverlay?.();sync();dialog.classList.remove('hidden');refreshAudioStatus();$('sound-settings-close').focus();};
function close(){dialog.classList.add('hidden');window.resumePlayerEngine?.();opener?.focus({preventScroll:true});}
$('sound-settings-close').onclick=close;$('game-sound-enabled').onchange=()=>{audio.configure({enabled:$('game-sound-enabled').checked});sync();};$('game-sound-volume').oninput=()=>{audio.configure({volume:Number($('game-sound-volume').value)});sync();};$('game-bgm-enabled').onchange=()=>{audio.configureBgm({enabled:$('game-bgm-enabled').checked});sync();};$('game-bgm-volume').oninput=()=>{audio.configureBgm({volume:Number($('game-bgm-volume').value)});sync();};
$('game-audio-unlock').onclick=async()=>{await audio.unlock();refreshAudioStatus();};
function refreshAudioStatus(){const state=audio.status(),wanted=audio.settings.enabled&&audio.settings.volume>0||audio.bgmSettings.enabled&&audio.bgmSettings.volume>0;button.textContent=wanted&&!state.ready&&!state.exporting?'音を開始':'音設定';battleSound.textContent=button.textContent;$('game-audio-unlock').hidden=state.ready||!wanted||state.exporting;}

window.addEventListener('kanji-audio-status',refreshAudioStatus);
function musicScene(){audio.setScene(document.body.dataset.activeTab==='battle'&&typeof soloBattlePending!=='undefined'&&!soloBattlePending&&typeof isBattleEnded!=='undefined'&&!isBattleEnded?'battle':'menu');}
new MutationObserver(musicScene).observe(document.body,{attributes:true,attributeFilter:['data-active-tab']});
for(const [id,options] of [['battle-turn-label',{childList:true,characterData:true,subtree:true}],['modal-result',{attributes:true,attributeFilter:['class']}],['screen-battle',{attributes:true,attributeFilter:['class']}]]){const el=$(id);if(el)new MutationObserver(musicScene).observe(el,options);}
const preview=$('replay-video-preview');if(preview){preview.addEventListener('play',()=>audio.setPreviewing(true));for(const event of ['pause','ended','emptied'])preview.addEventListener(event,()=>audio.setPreviewing(false));}
musicScene();refreshAudioStatus();
dialog.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const b=[...dialog.querySelectorAll('button,input')].filter(n=>!n.disabled),first=b[0],last=b.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
// Decorative UI does not access recipe outcomes or undiscovered characters.
})();
